from pathlib import Path
p=Path('index.html')
s=p.read_text()

def one(old,new,label):
    global s
    n=s.count(old)
    if n!=1:
        raise SystemExit(f'guard failed {label}: expected 1, got {n}')
    s=s.replace(old,new)

