old_map="function mapv(d){$('#view').innerHTML=`<div class=\"mapModes\"><button data-mode=\"satellite\" class=\"${state.mapMode==='satellite'?'on':''}\">Satellit</button><button data-mode=\"hybrid\" class=\"${state.mapMode==='hybrid'?'on':''}\">Hybrid</button><button data-mode=\"map\" class=\"${state.mapMode==='map'?'on':''}\">Karte</button></div><div id=\"map\" class=\"map\"></div><div class=\"mapNote\">Satellit/Hybrid ist für die Gewässeranalyse gedacht. Spots und Fishing-OS-Daten bleiben lokal; Kartenbilder brauchen Internet.</div><div class=\"mapActions\"><button class=\"btn\" id=\"mapSpot\">＋ Spot</button><button class=\"btn secondary\" id=\"mapWater\">＋ Gewässer</button></div><div class=\"section\"><h2>Gespeicherte Spots</h2></div>"
