one("$$('[data-mode]').forEach(b=>b.onclick=()=>{state.mapMode=b.dataset.mode;render()});$('#mapSpot').onclick=()=>spotForm(d,d.waters[0]?.id);$('#mapWater').onclick=()=>waterForm(d);$$('[data-spotrow]').forEach(b=>b.onclick=()=>spotDetail(d,d.spots.find(s=>s.id===b.dataset.spotrow)))}","$$('[data-mode]').forEach(b=>b.onclick=()=>{state.mapMode=b.dataset.mode;render()});let meMarker=null,meCircle=null;async function centerMe(){try{let p=await gpsOnce();if(meMarker)state.map.removeLayer(meMarker);if(meCircle)state.map.removeLayer(meCircle);meMarker=L.circleMarker([p.lat,p.lon],{radius:9,weight:3,color:'#fff',fillColor:'#0aa0a8',fillOpacity:1}).addTo(state.map).bindPopup('Dein aktueller Standort');if(Number.isFinite(p.accuracy))meCircle=L.circle([p.lat,p.lon],{radius:p.accuracy,weight:1,opacity:.5,fillOpacity:.08}).addTo(state.map);state.map.setView([p.lat,p.lon],Math.max(state.map.getZoom(),16));}catch{alert('Dein Standort konnte nicht gelesen werden. Prüfe die Standortfreigabe.')}}$('#mapMe').onclick=centerMe;centerMe();$('#mapSpot').onclick=()=>spotForm(d,d.waters[0]?.id);$('#mapWater').onclick=()=>waterForm(d);$$('[data-spotrow]').forEach(b=>b.onclick=()=>spotDetail(d,d.spots.find(s=>s.id===b.dataset.spotrow)))}",'map location logic')

old_stats="function stats(d){let catches=d.events.filter(e=>e.type==='catch'),lost=d.events.filter(e=>e.type==='lost'),sessions=d.days.filter(x=>x.endedAt),successful=sessions.filter(day=>d.events.some(e=>e.dayId===day.id&&e.type==='catch')).length,pressure={},temp={},wind={},lures={};"
